import React, { useState } from 'react';
import './styles/style.css'; // Zamiast używać importów z React Native, będziemy używać CSS
import { Link } from 'react-router-dom'; // do nawigacji w PWA
import ItemAdd from './ItemAdd';

interface ItemListProps {
  username: string;
  avatar: string;
  onLogout: () => void;
}

const ItemList: React.FC<ItemListProps> = ({ username, avatar, onLogout }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [showAddItem, setShowAddItem] = useState(false);
  const [activeMenu2, setActiveMenu2] = useState<number>(1);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleUserMenu = () => {
    setIsUserMenuOpen(!isUserMenuOpen);
  };

  const handleLogout = () => {
    if (window.confirm('Czy na pewno chcesz się wylogować?')) {
      onLogout();
    }
  };

  const navigateToAddItem = () => {
    setShowAddItem(true);
    setIsMenuOpen(false);
  };

  const navigateToList = () => {
    setShowAddItem(false);
  };

  if (showAddItem) {
    return (
      <ItemAdd
        username={username}
        avatar={avatar}
        onLogout={onLogout}
        onNavigateToList={navigateToList}
      />
    );
  }

  return (
    <div className="container">
      <div className="menu">
        <button onClick={toggleMenu} className="menu-icon-button">
          <img src="/assets/menu.png" alt="Menu" className="menu-icon" />
        </button>
        <img src="/assets/skinradar.png" alt="Logo" className="logo" />
        <button onClick={toggleUserMenu} className="user-avatar-button">
          <img src={avatar} alt="User Avatar" className="avatar" />
        </button>
      </div>

      <div className="scroll-container">
        {isMenuOpen && (
          <div className="dropdown-menu">
            <button className="dropdown-button">LISTA</button>
            <button className="dropdown-button" onClick={navigateToAddItem}>DODAJ</button>
          </div>
        )}

        {isUserMenuOpen && (
          <div className="user-menu">
            <span className="user-menu-text">{username}</span>
            <button className="logout-button" onClick={handleLogout}>
              <img src="/assets/logout.png" alt="Logout" className="logout-icon" />
            </button>
          </div>
        )}

        <div className="content">
          <h1>Witaj w aplikacji SkinRadar!</h1>
        </div>
      </div>

      <div className="menu2">
        {[require('./assets/settings.png'), require('./assets/bell.png'), require('./assets/questmark.png')].map((icon, idx) => (
          <button
            key={idx}
            onClick={() => setActiveMenu2(idx)}
            className="menu2-button"
            aria-label="Menu Icon"
          >
            <div className={`menu2-icon-wrapper ${activeMenu2 === idx ? 'active' : ''}`}>
              <img src={icon} alt="Menu Icon" className={`menu-button-icon ${activeMenu2 === idx ? 'active' : ''}`} />
            </div>
          </button>
        ))}
      </div>
    </div>
  );
};

export default ItemList;
